CREATE TABLE website_photos(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),slot TEXT NOT NULL,alt TEXT NOT NULL,caption TEXT NOT NULL,rights_note TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','published')),original_mime TEXT NOT NULL,original BLOB NOT NULL,preview BLOB NOT NULL,sha256 TEXT NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(business_id,slot));
CREATE TABLE backup_runs(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id),started_at INTEGER NOT NULL,finished_at INTEGER,status TEXT NOT NULL CHECK(status IN ('running','uploaded','failed','acknowledged')),directory TEXT NOT NULL,error TEXT);
